    # §3-9 — البحث العربي: الأصل المحفوظ لا يتغيّر، search_name حقل بحث مُطبَّع فقط
    op.execute("""
        CREATE OR REPLACE FUNCTION fn_normalize_arabic(p_text TEXT) RETURNS TEXT AS $$
            SELECT regexp_replace(
                     translate(
                       regexp_replace(coalesce(p_text, ''), '[ً-ْـ]', '', 'g'),
                       'أإآٱةىؤئ',
                       'ااااهيوي'
                     ),
                   '\\s+', ' ', 'g')
        $$ LANGUAGE sql IMMUTABLE;
    """)
    op.execute("""
        CREATE OR REPLACE FUNCTION trg_fn_clients_search_name() RETURNS TRIGGER AS $$
        BEGIN
            NEW.search_name := fn_normalize_arabic(NEW.name_ar);
            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
    """)
    op.execute("""
        CREATE TRIGGER trg_clients_search_name
            BEFORE INSERT OR UPDATE OF name_ar ON clients
            FOR EACH ROW EXECUTE FUNCTION trg_fn_clients_search_name();
    """)

    # §3-4 / §5 قاعدة ٢ + التعديل المعتمد §7-١: القيود المُرحّلة لا تُعدَّل ولا
    # تُحذف — يشمل هذا رفض إدراج سطر جديد على قيد POSTED (لا فقط UPDATE/DELETE).
    op.execute("""
        CREATE OR REPLACE FUNCTION trg_fn_journal_lines_immutable() RETURNS TRIGGER AS $$
        DECLARE
            v_status entry_status;
            v_entry_id BIGINT := COALESCE(NEW.entry_id, OLD.entry_id);
        BEGIN
            SELECT status INTO v_status FROM journal_entries WHERE id = v_entry_id;
            IF v_status = 'POSTED' THEN
                RAISE EXCEPTION 'لا يمكن إدراج أو تعديل أو حذف سطر قيد مُرحّل (entry_id=%)', v_entry_id;
            END IF;
            IF TG_OP = 'DELETE' THEN
                RETURN OLD;
            END IF;
            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
    """)
    op.execute("""
        CREATE TRIGGER trg_journal_lines_no_edit_when_posted
            BEFORE INSERT OR UPDATE OR DELETE ON journal_lines
            FOR EACH ROW EXECUTE FUNCTION trg_fn_journal_lines_immutable();
    """)

    # توسعة على الوثيقة: عملة السطر يجب أن تطابق عملة الحساب المرجعي دائماً،
    # وإلا فحص "التوازن داخل كل عملة" (§2-3) يتحقق على تصنيف خاطئ.
    op.execute("""
        CREATE OR REPLACE FUNCTION trg_fn_journal_lines_currency_match() RETURNS TRIGGER AS $$
        DECLARE
            v_acc_ccy TEXT;
        BEGIN
            SELECT currency_code INTO v_acc_ccy FROM accounts WHERE id = NEW.account_id;
            -- ٥٩٠٠ فروق التقريب هو الاستثناء الوحيد المُصرَّح به في الوثيقة (§2-5):
            -- "حساب واحد" بلا عملة طبيعية يستقبل فروقاً بأي عملة — currency_code
            -- الحساب NULL في هذه الحالة فقط، فيُستثنى من فحص المطابقة.
            IF v_acc_ccy IS NOT NULL AND v_acc_ccy IS DISTINCT FROM NEW.currency_code THEN
                RAISE EXCEPTION 'عملة السطر (%) لا تطابق عملة الحساب % (%)', NEW.currency_code, NEW.account_id, v_acc_ccy;
            END IF;
            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
    """)
    op.execute("""
        CREATE TRIGGER trg_journal_lines_currency_match
            BEFORE INSERT OR UPDATE ON journal_lines
            FOR EACH ROW EXECUTE FUNCTION trg_fn_journal_lines_currency_match();
    """)

    # §3-4 قاعدة ١: شرط التوازن الوحيد — يُفحص لحظة انتقال الحالة إلى POSTED
    op.execute("""
        CREATE OR REPLACE FUNCTION trg_fn_journal_entries_check_balance() RETURNS TRIGGER AS $$
        DECLARE
            v_unbalanced RECORD;
        BEGIN
            IF NEW.status = 'POSTED' AND OLD.status IS DISTINCT FROM 'POSTED' THEN
                SELECT currency_code, SUM(debit) - SUM(credit) AS diff
                  INTO v_unbalanced
                  FROM journal_lines
                 WHERE entry_id = NEW.id
                 GROUP BY currency_code
                HAVING SUM(debit) <> SUM(credit)
                 LIMIT 1;
                IF FOUND THEN
                    RAISE EXCEPTION 'القيد % غير متوازن بعملة % (الفرق %)', NEW.entry_no, v_unbalanced.currency_code, v_unbalanced.diff;
                END IF;
            END IF;
            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
    """)
    op.execute("""
        CREATE TRIGGER trg_journal_entries_check_balance
            BEFORE UPDATE ON journal_entries
            FOR EACH ROW EXECUTE FUNCTION trg_fn_journal_entries_check_balance();
    """)

    # التعديل المعتمد §7-٢: قيد جديد يُنشأ دائماً بحالة DRAFT — الترحيل يمر
    # حصراً عبر DRAFT → POSTED عن طريق UPDATE لاحق، لا عبر INSERT مباشر بحالة POSTED.
    op.execute("""
        CREATE OR REPLACE FUNCTION trg_fn_journal_entries_insert_draft_only() RETURNS TRIGGER AS $$
        BEGIN
            IF NEW.status <> 'DRAFT' THEN
                RAISE EXCEPTION 'كل قيد جديد يُنشأ بحالة DRAFT حصراً — الترحيل عبر DRAFT → POSTED (entry_no=%, status=%)', NEW.entry_no, NEW.status;
            END IF;
            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
    """)
    op.execute("""
        CREATE TRIGGER trg_journal_entries_insert_draft_only
            BEFORE INSERT ON journal_entries
            FOR EACH ROW EXECUTE FUNCTION trg_fn_journal_entries_insert_draft_only();
    """)

    # §5-11: audit_log سجل بلا تعديل (Append-only)
    op.execute("""
        CREATE OR REPLACE FUNCTION trg_fn_append_only() RETURNS TRIGGER AS $$
        BEGIN
            RAISE EXCEPTION 'جدول % سجل بلا تعديل (append-only)', TG_TABLE_NAME;
        END;
        $$ LANGUAGE plpgsql;
    """)
    op.execute("""
        CREATE TRIGGER trg_audit_log_append_only
            BEFORE UPDATE OR DELETE ON audit_log
            FOR EACH ROW EXECUTE FUNCTION trg_fn_append_only();
    """)


